def solve(inputs: dict) -> float:
    remainders = inputs['remainders']
    moduli = inputs['moduli']

    # Extended GCD to find modular inverse
    def egcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = egcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def modinv(a, m):
        gcd, x, _ = egcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # Chinese Remainder Theorem
    N = 1
    for m in moduli:
        N *= m

    result = 0
    for i in range(len(remainders)):
        Ni = N // moduli[i]
        Mi = modinv(Ni, moduli[i])
        result += remainders[i] * Ni * Mi

    result = result % N
    return float(result)
"}

